const modal=document.querySelector('dialog');document.querySelectorAll('.photo').forEach(button=>button.addEventListener('click',()=>{modal.querySelector('img').src=button.dataset.src;modal.querySelector('img').alt=button.dataset.caption;modal.querySelector('p').textContent=button.dataset.caption;modal.showModal()}));document.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal)modal.close()});
